import{_ as e,W as a,X as i,$ as n}from"./framework-9028b4f1.js";const d={},c=n('<h1 id="stl函数与用法" tabindex="-1"><a class="header-anchor" href="#stl函数与用法" aria-hidden="true">#</a> STL函数与用法</h1><h2 id="二分查找" tabindex="-1"><a class="header-anchor" href="#二分查找" aria-hidden="true">#</a> 二分查找</h2><ul><li><code>lower_bound(begin(),end(),val)</code> //返回一个非递减序列[first, last)中的第一个大于等于值val的位置</li><li><code>upper_bound(begin(),end(),val)</code> //返回一个非递减序列[first, last)中的第一个大于值val的位置</li></ul><h2 id="集合函数" tabindex="-1"><a class="header-anchor" href="#集合函数" aria-hidden="true">#</a> 集合函数</h2><ul><li>并集</li></ul><p><code>set_union(a.begin(),a.end(),b.begin(),b.end(),c.begin())</code> //将a，b集合中的元素并集存入到c中</p><ul><li>交集</li></ul><p><code>set_intersection(a.begin(),a.end(),b.begin(),b.end(),c.begin())</code> //将a，b集合中的元素交集存入到c中</p><ul><li>差集</li></ul><p><code>set_difference(a.begin(),a.end(),b.begin(),b.end(),c.begin())</code> //将a，b集合中的元素差集存入到c中</p><h2 id="全排列" tabindex="-1"><a class="header-anchor" href="#全排列" aria-hidden="true">#</a> 全排列</h2><ul><li><code>next_permutation(a.begin(),a.end())</code> //得到序列a的下一个排列</li></ul>',12),l=[c];function t(r,o){return a(),i("div",null,l)}const h=e(d,[["render",t],["__file","STL函数与用法.html.vue"]]);export{h as default};
